(async()=>{
const p=figma.currentPage,F=s=>p.findOne(n=>n.type==='FRAME'&&n.name===s),draft=F('P02-草稿箱'),transfer=F('P02-转报-来源信息');if(!draft||!transfer)throw Error('缺少草稿箱或转报表单');
const fonts=new Map();for(const t of p.findAll(n=>n.type==='TEXT'))for(const f of(t.fontName===figma.mixed?t.getRangeAllFontNames(0,t.characters.length):[t.fontName]))fonts.set(JSON.stringify(f),f);await Promise.all([...fonts.values()].map(f=>figma.loadFontAsync(f)));
const go=n=>({type:'NODE',destinationId:n.id,navigation:'NAVIGATE',transition:null,resetScrollPosition:true}),B={type:'BACK'},on=(n,a)=>n.setReactionsAsync([{trigger:{type:'ON_CLICK'},actions:[a]}]);
const find=(r,s)=>r.findOne(n=>n.name==='操作 / '+s),rename=(n,s)=>{n.name='操作 / '+s;const t=n.findOne(n=>n.type==='TEXT');t.characters=s;t.name=s;};
const body=draft.findOne(n=>n.name==='内容容器 / 自动布局');let row=body.children.find(n=>n.name==='草稿 / 转报线索');if(!row){const sample=body.children.find(n=>n.name.startsWith('草稿 / '));if(!sample)throw Error('缺少草稿卡模板');row=sample.clone();body.appendChild(row);row.name='草稿 / 转报线索';const c=row.children.find(n=>n.name.startsWith('草稿摘要 / '));c.name='草稿摘要 / 转报线索';const ts=c.findAll(n=>n.type==='TEXT');['银色钥匙转报','线索 · 来源许可待确认','继续编辑'].forEach((s,i)=>{ts[i].characters=s;ts[i].name=s;});const old=row.children.find(n=>n.type==='INSTANCE'),comp=p.findOne(n=>n.type==='COMPONENT'&&n.name==='插画 / 贴纸铅笔');if(old&&comp){const i=comp.createInstance();i.name='插画 / 转报线索';i.rescale(64/comp.width);row.insertChild(row.children.indexOf(old),i);old.remove();}}await on(row,go(transfer));
let saved=0;for(const[name,label]of[['P02-发布-钥匙基础信息','保存草稿回我的'],['P02-发布-水杯分类建议','保存草稿'],['P02-寻物-基础信息','保存草稿'],['P02-转报-来源信息','保存草稿']]){const f=F(name);if(!f)throw Error(name);const b=find(f,label)||find(f,'保存草稿');if(!b)throw Error('缺少保存 '+name);rename(b,'保存草稿');await on(b,go(draft));saved++;}
let returned=0;for(const[name,label]of[['P04-招领详情-银色钥匙','返回首页'],['P04-寻物详情-黑色保温杯','返回首页继续浏览']]){const f=F(name),b=find(f,label)||find(f,'返回上一页');if(!b)throw Error('缺少详情返回');rename(b,'返回上一页');await on(b,B);returned++;}
let edited=0;for(const[name,label]of[['P06-水杯-关联候选线索','返回水杯草稿'],['P02-发布-水杯候选比较','返回修改原草稿'],['P02-发布-水杯公开预览','返回修改草稿'],['P04-寻物详情-黑色旅行杯','继续修改水杯草稿']]){const f=F(name),b=f&&(find(f,label)||find(f,'继续编辑水杯草稿'));if(b){rename(b,'继续编辑水杯草稿');edited++;}}
const fresh=p.findAll(n=>(n.type==='FRAME'||n.type==='INSTANCE')&&n.name==='操作 / 去发布寻物');for(const n of fresh)rename(n,'新建寻物信息');
console.log(JSON.stringify({patch:'repair-flow-final',draft:row.id,saved,returned,edited,newSearchLabels:fresh.length}));figma.notify('草稿与返回路径已校正');
})().catch(e=>{console.error(e);figma.notify(String(e),{error:true,timeout:15000});});
